            # 工作区始终清理，绝不留下含私钥的暂存副本。
            shutil.rmtree(txn, ignore_errors=True)
            raise
        except OSError as exc:
            # 换入/标记阶段的文件系统故障：保留事务区，交由下次持锁
            # 前滚/回滚；本次报 503。
            raise BackupError(503, f"restore interrupted by a filesystem error: {exc}")

    return 201, {
        "wallet_id": wallet_id,
        "snapshot_id": snapshot_id,
        "manifest": manifest,
        "manifest_sha256": digest,
    }


