h.service.commit_asset_operation("alice", "op-1")
snap = tempfile.mktemp(suffix=".tar")
create_backup(src, "alice", "s1", snap)

raw = open(snap, "rb").read()

def repack(modify):
    out = {}
    with tarfile.open(fileobj=io.BytesIO(raw)) as t:
        for info in t:
            f = t.extractfile(info)
            out[info.name] = f.read() if f else b""
    modify(out)
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w") as t:
        for name, data in out.items():
            i = tarfile.TarInfo(name); i.size = len(data); i.mode=0o600
            t.addfile(i, io.BytesIO(data))
    return buf.getvalue()

# 1) 篡改份额私钥（内容与 manifest sha 不符）-> 503
def m1(out):
    key = "shares/alice/share-1.json"
    rec = json.loads(out[key]); rec["private_key"] = "11"*32
    out[key] = (json.dumps(rec)+"\n").encode()
p = tempfile.mktemp(suffix=".tar"); open(p,"wb").write(repack(m1))
try: restore_backup(tempfile.mkdtemp(), "alice", p); print("FAIL priv tamper")
except BackupError as e: print("private tamper (hash mismatch) ->", e.status)

# 2) 篡改份额私钥并同步 manifest 哈希 -> 应被公私钥校验拒绝
def m2(out):
    key = "shares/alice/share-1.json"
    rec = json.loads(out[key]); rec["private_key"] = "11"*32
    data = (json.dumps(rec)+"\n").encode(); out[key] = data
    man = json.loads(out["manifest.json"])
    for f in man["files"]:
        if f["path"] == key:
            import hashlib; f["sha256"] = hashlib.sha256(data).hexdigest(); f["bytes"] = len(data)
    out["manifest.json"] = json.dumps(man).encode()
p = tempfile.mktemp(suffix=".tar"); open(p,"wb").write(repack(m2))
try: restore_backup(tempfile.mkdtemp(), "alice", p); print("FAIL key tamper")
except BackupError as e: print("key mismatch (crypto) ->", e.status)

# 3) 篡改账本余额（assets）并同步哈希 -> 应被账本/事件一致性拒绝
def m3(out):
    key = "assets/alice.json"
    led = json.loads(out[key])
    led["assets"]["BTC"]["balance"] = 999
    data = json.dumps(led).encode(); out[key] = data
    man = json.loads(out["manifest.json"])
    for f in man["files"]:
        if f["path"] == key:
            import hashlib; f["sha256"] = hashlib.sha256(data).hexdigest(); f["bytes"] = len(data)
    out["manifest.json"] = json.dumps(man).encode()
p = tempfile.mktemp(suffix=".tar"); open(p,"wb").write(repack(m3))
try: restore_backup(tempfile.mkdtemp(), "alice", p); print("FAIL ledger tamper")
except BackupError as e: print("ledger/event mismatch ->", e.status)

# 4) 篡改审计（删掉一个 seq）并同步哈希 -> 审计 seq 不连续 -> 503
def m4(out):
